package com.dmitry.myai.infinix.bridge;
import android.accessibilityservice.AccessibilityService; import android.accessibilityservice.GestureDescription; import android.graphics.Path; import android.view.accessibility.AccessibilityEvent; import android.view.accessibility.AccessibilityNodeInfo;
public class MyAiAccessibilityService extends AccessibilityService { private static MyAiAccessibilityService instance; public static boolean isConnected(){return instance!=null;} public void onServiceConnected(){instance=this;log("SERVICE CONNECTED — INFINIX ALPHA");} public void onAccessibilityEvent(AccessibilityEvent e){} public void onInterrupt(){log("SERVICE INTERRUPTED");} public void onDestroy(){if(instance==this)instance=null;super.onDestroy();} public static void home(){if(instance!=null)instance.performGlobalAction(GLOBAL_ACTION_HOME);else throw new IllegalStateException("Control Bridge not connected");} public static void back(){if(instance!=null)instance.performGlobalAction(GLOBAL_ACTION_BACK);else throw new IllegalStateException("Control Bridge not connected");} public static void scrollDown(){if(instance==null)throw new IllegalStateException("Control Bridge not connected");AccessibilityNodeInfo r=instance.getRootInActiveWindow();if(r!=null&&r.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD))return;Path p=new Path();p.moveTo(540,1500);p.lineTo(540,500);GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,500)).build();instance.dispatchGesture(g,null,null);} public static void log(String s){android.util.Log.i("MyAI-Infinix",s);}}
